  ('fin','الإدارة المالية','💰','الصرف والمشتريات، العهد، الكفالات، سندات القبض، والتقارير المالية.',4),
  ('ceo','مكتب الرئيس التنفيذي','🗂️','القرارات الإدارية، التوقيع والختم، المواعيد والمحاضر، وخدمة المستفيدين والشكاوى.',5),
  ('edu_m','قسم تعليم البنين','📖','حلقات البنين: التسجيل، فتح الحلقات، المعلمون، الشهادات، والمستلزمات التعليمية.',6),
  ('edu_f','قسم التعليم النسائي','🌸','حلقات النساء والفتيات: التسجيل، فتح الحلقات، المعلمات، الشهادات، والمستلزمات.',7),
  ('qa','قسم الجودة التعليمية','⭐','الزيارات الإشرافية، تقييم أداء المعلمين، اعتماد الخطط التعليمية، ومعالجة ملاحظات الجودة.',8),
  ('vol','قسم التطوع','🤝','تسجيل المتطوعين، الفرص التطوعية، توثيق الساعات، والشهادات والفرق التطوعية.',9)
on conflict (id) do update set name=excluded.name, icon=excluded.icon,
  descr=excluded.descr, sort_order=excluded.sort_order;


